#include <bits/stdc++.h>
using namespace std;
int main(){int n,m;cin>>n>>m;vector<vector<int>>a(n,vector<int>(m)),d(n,vector<int>(m,-1));for(auto&r:a)for(auto&x:r)cin>>x;if(a[0][0]||a[n-1][m-1]){cout<<-1;return 0;}queue<pair<int,int>>q;q.push({0,0});d[0][0]=0;int dx[]={1,-1,0,0},dy[]={0,0,1,-1};while(!q.empty()){auto[x,y]=q.front();q.pop();for(int k=0;k<4;k++){int u=x+dx[k],v=y+dy[k];if(u>=0&&u<n&&v>=0&&v<m&&!a[u][v]&&d[u][v]==-1){d[u][v]=d[x][y]+1;q.push({u,v});}}}cout<<d[n-1][m-1]<<"\n";}

