using namespace std;
int main(){int n,m;cin>>n>>m;vector<int>p(n+1),sz(n+1,1);iota(p.begin(),p.end(),0);auto find=[&](int x){while(x!=p[x]){p[x]=p[p[x]];x=p[x];}return x;};int ans=n;while(m--){int a,b;cin>>a>>b;a=find(a);b=find(b);if(a!=b){if(sz[a]<sz[b])swap(a,b);p[b]=a;sz[a]+=sz[b];ans--;}}cout<<ans<<"\n";}

